import java.util.HashSet;
import java.util.Set;

class BrokenItem {
    private String sku;
    public BrokenItem(String sku) { this.sku = sku; }

    // Overrode equals()...
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        return sku.equals(((BrokenItem) obj).sku);
    }
    // ...BUT FORGOT TO OVERRIDE hashCode()! Disastrous contract violation!
}

public class ContractBreakerDemo {
    public static void main(String[] args) {
        Set<BrokenItem> warehouse = new HashSet<>();
        BrokenItem item1 = new BrokenItem("SKU-400");
        warehouse.add(item1);

        BrokenItem item2 = new BrokenItem("SKU-400");

        // Logically equal:
        System.out.println("item1.equals(item2): " + item1.equals(item2)); // true!

        // But HashSet cannot find it!
        boolean found = warehouse.contains(item2);
        System.out.println("warehouse.contains(item2): " + found); // FALSE! GHOST OBJECT!
    }
}

