import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

class FixedItem {
    private String sku;
    public FixedItem(String sku) { this.sku = sku; }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        return Objects.equals(sku, ((FixedItem) obj).sku);
    }

    // Contract upheld: equal objects produce equal hash codes
    @Override
    public int hashCode() {
        return Objects.hash(sku);
    }
}

public class ContractFixedDemo {
    public static void main(String[] args) {
        Set<FixedItem> warehouse = new HashSet<>();
        warehouse.add(new FixedItem("SKU-400"));

        FixedItem searchTarget = new FixedItem("SKU-400");

        // HashSet looks in the exact right bucket!
        System.out.println("warehouse.contains(searchTarget): " + warehouse.contains(searchTarget)); // true!
    }
}

