import java.util.Objects;

class GoodEntity {
    private int id;
    public GoodEntity(int id) { this.id = id; }
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        return id == ((GoodEntity) o).id;
    }
    @Override
    public int hashCode() { return Objects.hash(id); }
}

class BadEntity {
    private int id;
    public BadEntity(int id) { this.id = id; }
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        return id == ((BadEntity) o).id;
    }
    // Omits hashCode!
}

class ContractValidator {
    public static boolean verifyContract(Object a, Object b) {
        boolean eq = a.equals(b);
        boolean hashEq = (a.hashCode() == b.hashCode());
        if (eq && !hashEq) {
            System.out.println("VIOLATION: Objects are equal, but hashCodes differ!");
            return false;
        } else {
            System.out.println("COMPLIANT: Contract satisfied");
            return true;
        }
    }
}

public class ValidatorApp {
    public static void main(String[] args) {
        ContractValidator.verifyContract(new GoodEntity(10), new GoodEntity(10));
        ContractValidator.verifyContract(new BadEntity(10), new BadEntity(10));
    }
}

import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

class VipMember {
    private String nationalId;
    private String fullName;

    public VipMember(String nationalId, String fullName) {
        this.nationalId = nationalId;
        this.fullName = fullName;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        VipMember other = (VipMember) obj;
        return Objects.equals(nationalId, other.nationalId);
    }

    @Override
    public int hashCode() {
        return Objects.hash(nationalId);
    }
}

class MemberRegistry {
    private Set<VipMember> members = new HashSet<>();

    public boolean register(VipMember m) {
        return members.add(m);
    }

    public int totalCount() {
        return members.size();
    }
}

public class RegistryApp {
    public static void main(String[] args) {
        MemberRegistry reg = new MemberRegistry();
        System.out.println("Registered Alice: " + reg.register(new VipMember("NID-100", "Alice Cooper")));
        System.out.println("Registered Dup:   " + reg.register(new VipMember("NID-100", "Alice C.")));
        System.out.println("Registered Bob:   " + reg.register(new VipMember("NID-200", "Bob Dylan")));
        System.out.println("Total count:      " + reg.totalCount());
    }
}

