import java.util.Objects;

class PersonKey {
    private String firstName;
    private String lastName;

    public PersonKey(String first, String last) {
        this.firstName = first;
        this.lastName = last;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        PersonKey other = (PersonKey) obj;
        return Objects.equals(firstName, other.firstName) &&
               Objects.equals(lastName, other.lastName);
    }

    // BUG: Omits lastName from hashCode! Violates field alignment
    @Override
    public int hashCode() {
        return Objects.hash(firstName);
    }
}

public class FieldMismatchBugApp {
    public static void main(String[] args) {
        PersonKey p1 = new PersonKey("John", "Smith");
        PersonKey p2 = new PersonKey("John", "Smith");

        System.out.println("p1.equals(p2): " + p1.equals(p2));
        System.out.println("Hashes match: " + (p1.hashCode() == p2.hashCode()));
    }
}

