import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

class MutableAccount {
    private String accountId;
    public MutableAccount(String accountId) {
        this.accountId = accountId;
    }
    public void setAccountId(String newId) {
        this.accountId = newId;
    }
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        MutableAccount other = (MutableAccount) obj;
        return Objects.equals(accountId, other.accountId);
    }
    @Override
    public int hashCode() {
        return Objects.hash(accountId);
    }
}

public class MutableKeyApp {
    public static void main(String[] args) {
        Map<MutableAccount, String> accountMap = new HashMap<>();
        MutableAccount acc = new MutableAccount("ORIGINAL-ID");
        accountMap.put(acc, "Active Account Profile");

        acc.setAccountId("MUTATED-ID");

        System.out.println("Contains mutated key: " + accountMap.containsKey(acc));
        System.out.println("Map size: " + accountMap.size());
    }
}
